import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, fetchDurationOptions, createUserExamData, getAllFranchises } from '../services/api';

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    examName: '',
    date: '',
    durationInMinutes: '',
    status: 'inprogress',
    franchiseId: '',
  });
  const [franchiseList, setFranchiseList] = useState([]);
  const [durationList, setDurationList] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [userFullName, setUserFullName] = useState('');
  const [isSuperAdmin, setIsSuperAdmin] = useState(false);

  const validExamNames = [
    'ServiceNow: CAD', 'ServiceNow: CSA', 'ServiceNow: Platform Developer',
    'ServiceNow: HR AND IMPLEMENTATION', 'ServiceNow: CLOUD ARCHITECTURE',
    'Salesforce developer', 'Salesforce administrators', 'Google cloud', 
    'Mulesoft', 'Fusion', 'PSI'
  ];

  const validStatuses = ['completed', 'absent', 'inprogress'];

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        if (isSuperAdmin) {
          // If the user is superadmin, fetch all available franchises
          const allFranchises = await getAllFranchises(); // Create a function to fetch all franchises
          setFranchiseList(allFranchises);
        } else {
          // If the user is not a superadmin, fetch associated franchises
          const [franchiseData, durationData] = await Promise.all([
            getAssociatedFranchises(),
            fetchDurationOptions(),
          ]);

          if (!Array.isArray(franchiseData) || franchiseData.length === 0) {
            throw new Error('No associated franchises found for the user.');
          }

          if (!Array.isArray(durationData.options) || durationData.options.length === 0) {
            throw new Error('No exam durations available.');
          }

          setFranchiseList(franchiseData[0]);
          setDurationList(durationData.options);
        }
      } catch (error) {
        setError(error.message || 'Failed to fetch data.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [isSuperAdmin]); // Include `isSuperAdmin` in the dependency array

  useEffect(() => {
    // Replace this logic with your actual logic to check if the user is a superadmin
    const userRole = getUserRole(); // This could be from context, props, or session storage
    setIsSuperAdmin(userRole === 'superadmin');
  }, []);

  const handleExamDataChange = (e) => {
    const { name, value } = e.target;
    setExamData((prevData) => ({
      ...prevData,
      [name]: name === 'durationInMinutes' ? parseInt(value, 10) : value,
    }));
  };

  const handleUserFullNameChange = (e) => {
    const value = e.target.value;
    setUserFullName(value);
    setExamData((prevData) => ({
      ...prevData,
      name: value, // Add userFullName to examData
    }));
  };

  const validateForm = () => {
    if (!userFullName.trim()) {
      return 'Please provide the full name.';
    }
    if (!examData.examName || !validExamNames.includes(examData.examName)) {
      return 'Please select a valid exam name.';
    }
    if (!examData.status || !validStatuses.includes(examData.status.toLowerCase())) {
      return 'Please select a valid status.';
    }
    if (!examData.date) {
      return 'Please provide the exam date.';
    }
    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) {
      return 'Invalid date format.';
    }
    if (isNaN(examData.durationInMinutes) || examData.durationInMinutes <= 0) {
      return 'Please select a valid exam duration.';
    }
    if (!examData.franchiseId) {
      return 'Please select a franchise.';
    }
    return null;
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();
  
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }
  
    setLoading(true);
    try {
      const payload = {
        examData: [
          {
            name: userFullName,
            examName: examData.examName,
            date: new Date(examData.date).toISOString().split('T')[0], // Format the date
            durationInMinutes: parseInt(examData.durationInMinutes, 10),
            status: examData.status.toLowerCase(),
            franchiseId: examData.franchiseId,
          },
        ],
      };
  
      console.log('Sending Exam Data:', payload);
  
      // Send exam data to the franchise-specific endpoint
      await createUserExamData(payload.examData, examData.franchiseId); // Pass examData as an array
  
      setSuccess('Exam data created successfully!');
  
      // Reset form state
      setExamData({
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'inprogress',
        franchiseId: '',
      });
      setUserFullName('');
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || error.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Associated Franchise</h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        {/* Form fields go here */}
      </form>
    </div>
  );
};

export default AssociatedFranchises;
